item.aggregated_output:
  1	import {
  2		copyExpectedHead,
  3		copyGenerationRecord,
  4		hasSharedBacking,
  5		headsEqual,
  6		isBlobDigest,
  7		isClosedArray,
  8		isClosedRecord,
  9		isGenerationId,
 10		isStorageObjectId,
 11	} from "./internal/validation.js";
 12	import type {
 13		BlobDigest,
 14		ExpectedHead,
 15		GenerationId,
 16		GenerationRecord,
 17		PresentHead,
 18		StorageObjectId,
 19	} from "./types.js";
 20	import { digestBlob, digestClosure } from "./values.js";
 21	
 22	export const AHE_RECLAMATION_LOCAL_ONLY_POLICY_DIGEST =
 23		"53775c5c1ee01e346f588966d6e7acb876df2bd8b2abcbe2b2591f216f7d4d9b";
 24	
 25	export const AHE_RECLAMATION_ERROR_CODES = Object.freeze([
 26		"AHE_RECLAMATION_INVALID_ARGUMENT",
 27		"AHE_RECLAMATION_RETRY_REQUIRED",
 28		"AHE_RECLAMATION_CORRUPT",
 29		"AHE_RECLAMATION_STORE_CLOSED",
 30		"AHE_RECLAMATION_STORE_POISONED",
 31		"AHE_RECLAMATION_SUBSTRATE_FAILURE",
 32	] as const);
 33	
 34	export type AheReclamationErrorCode = (typeof AHE_RECLAMATION_ERROR_CODES)[number];
 35	
 36	export type AheReclamationInput = Readonly<{
 37		activeGenerationId: GenerationId;
 38		availabilityPolicyDigest: string;
 39		closedEpoch: number;
 40		expectedHead: PresentHead;
 41		lineageFloor: Readonly<{
 42			deleteGenerationIds: readonly GenerationId[];
 43			expectedBaseExpectedHead: ExpectedHead;
 44			generationId: GenerationId;
 45			replacementBaseExpectedHead: Readonly<{ kind: "none"; objectId: StorageObjectId }>;
 46		}>;
 47		objectId: StorageObjectId;
 48		rollbackGenerationIds: readonly [GenerationId, GenerationId];
 49	}>;
 50	
 51	export type AheReclamationReceipt = Readonly<{
 52		activeGenerationId: GenerationId;
 53		availabilityPolicyDigest: string;
 54		closedEpoch: number;
 55		deletedBlobDigests: readonly BlobDigest[];
 56		deletedGenerationIds: readonly GenerationId[];
 57		deletedPromotionCount: number;
 58		expectedHead: PresentHead;
 59		floor: Readonly<{
 60			expectedFormerBaseExpectedHead: ExpectedHead;
 61			generationId: GenerationId;
 62			normalizedThisCall: boolean;
 63			replacementBaseExpectedHead: Readonly<{ kind: "none"; objectId: StorageObjectId }>;
 64		}>;
 65		objectId: StorageObjectId;
 66		reclaimedGenerationIds: readonly GenerationId[];
 67		rollbackGenerationIds: readonly [GenerationId, GenerationId];
 68	}>;
 69	
 70	export interface AheReclamationMaintenance {
 71		reclaimClosedEpoch(input: unknown): Promise<AheReclamationReceipt>;
 72	}
 73	
 74	export type AheReclamationPromotion = Readonly<{
 75		digest: BlobDigest;
 76		generationId: GenerationId;
 77		objectId: StorageObjectId;
 78	}>;
 79	
 80	export type AheReclamationBlobObservation = Readonly<{
 81		bytes: Uint8Array;
 82		digest: BlobDigest;
 83	}>;
 84	
 85	export type AheReclamationSnapshot = Readonly<{
 86		blobs: readonly AheReclamationBlobObservation[];
 87		generations: readonly GenerationRecord[];
 88		head: ExpectedHead;
 89		promotions: readonly AheReclamationPromotion[];
 90	}>;
 91	
 92	export type AheReclamationDecision = Readonly<{
 93		deleteBlobDigests: readonly BlobDigest[];
 94		deleteGenerationIds: readonly GenerationId[];
 95		deletePromotions: readonly AheReclamationPromotion[];
 96		floor: Readonly<{
 97			generation: GenerationRecord;
 98			normalizedThisCall: boolean;
 99			rewrittenGeneration: GenerationRecord;
100		}>;
101		input: AheReclamationInput;
102	}>;
103	
104	/** Closed reclamation failure shared by the strict native owners. */
105	export class AheReclamationError extends Error {
106		readonly code: AheReclamationErrorCode;
107	
108		/**
109		 * Creates one classified reclamation failure.
110		 * @param code - Closed public error code.
111		 * @param message - Stable diagnostic summary.
112		 * @param options - Optional substrate cause.
113		 */
114		constructor(code: AheReclamationErrorCode, message: string, options?: ErrorOptions) {
115			super(message, options);
116			this.code = code;
117			Object.defineProperty(this, "name", { configurable: true, value: "AheReclamationError" });
118		}
119	}
120	
121	function failure(code: AheReclamationErrorCode, message: string, cause?: unknown): AheReclamationError {
122		return Object.freeze(new AheReclamationError(code, message, cause === undefined ? undefined : { cause }));
123	}
124	
125	function invalid(message: string): never {
126		throw failure("AHE_RECLAMATION_INVALID_ARGUMENT", message);
127	}
128	
129	function retry(message: string): never {
130		throw failure("AHE_RECLAMATION_RETRY_REQUIRED", message);
131	}
132	
133	function corrupt(message: string): never {
134		throw failure("AHE_RECLAMATION_CORRUPT", message);
135	}
136	
137	function cloneHead(head: ExpectedHead): ExpectedHead {
138		return Object.freeze({ ...head });
139	}
140	
141	function cloneGeneration(generation: GenerationRecord): GenerationRecord {
142		return Object.freeze({
143			...generation,
144			baseExpectedHead: cloneHead(generation.baseExpectedHead),
145			closure: Object.freeze(generation.closure.map((reference) => Object.freeze({ ...reference }))),
146		});
147	}
148	
149	function copyGenerationIds(value: unknown): readonly GenerationId[] {
150		if (!isClosedArray(value)) invalid("deleteGenerationIds must be one exact dense array");
151		const ids: GenerationId[] = [];
152		for (const candidate of value) {
153			if (!isGenerationId(candidate)) invalid("deleteGenerationIds must contain canonical generation IDs");
154			ids.push(candidate);
155		}
156		if (new Set(ids).size !== ids.length || ids.some((id, index) => index > 0 && id <= (ids[index - 1] ?? id))) {
157			invalid("deleteGenerationIds must be unique and canonically ordered");
158		}
159		return Object.freeze(ids);
160	}
161	
162	function copyRollbackIds(value: unknown): readonly [GenerationId, GenerationId] {
163		if (!isClosedArray(value) || value.length !== 2 || !isGenerationId(value[0]) || !isGenerationId(value[1])) {
164			invalid("rollbackGenerationIds must contain exactly two canonical IDs");
165		}
166		if (value[0] === value[1]) invalid("rollbackGenerationIds must be distinct");
167		return Object.freeze([value[0], value[1]] as const);
168	}
169	
170	/**
171	 * Validates, detaches, and deeply freezes the AHE subset emitted by D.109a.
172	 * @param value - Untrusted reclamation request.
173	 * @returns Exact captured maintenance input.
174	 */
175	export function captureAheReclamationInput(value: unknown): AheReclamationInput {
176		try {
177			if (
178				!isClosedRecord(value, [
179					"activeGenerationId",
180					"availabilityPolicyDigest",
181					"closedEpoch",
182					"expectedHead",
183					"lineageFloor",
184					"objectId",
185					"rollbackGenerationIds",
186				]) ||
187				!isStorageObjectId(value.objectId) ||
188				!isGenerationId(value.activeGenerationId) ||
189				value.availabilityPolicyDigest !== AHE_RECLAMATION_LOCAL_ONLY_POLICY_DIGEST ||
190				!Number.isSafeInteger(value.closedEpoch) ||
191				Number(value.closedEpoch) < 0 ||
192				!isClosedRecord(value.lineageFloor, [
193					"deleteGenerationIds",
194					"expectedBaseExpectedHead",
195					"generationId",
196					"replacementBaseExpectedHead",
197				]) ||
198				!isGenerationId(value.lineageFloor.generationId)
199			) {
200				invalid("reclamation input must be one exact validated record");
201			}
202			const expectedHead = copyExpectedHead(value.expectedHead, value.objectId);
203			const expectedBaseExpectedHead = copyExpectedHead(value.lineageFloor.expectedBaseExpectedHead, value.objectId);
204			const replacementBaseExpectedHead = copyExpectedHead(
205				value.lineageFloor.replacementBaseExpectedHead,
206				value.objectId
207			);
208			if (
209				expectedHead?.kind !== "present" ||
210				expectedHead.generationId !== value.activeGenerationId ||
211				expectedBaseExpectedHead === undefined ||
212				replacementBaseExpectedHead?.kind !== "none"
213			) {
214				invalid("reclamation input identities must agree");
215			}
216			const rollbackGenerationIds = copyRollbackIds(value.rollbackGenerationIds);
217			const deleteGenerationIds = copyGenerationIds(value.lineageFloor.deleteGenerationIds);
218			if (deleteGenerationIds.length === 0 && expectedBaseExpectedHead.kind === "present") {
219				invalid("an empty reclamation prefix cannot retain a former floor parent");
220			}
221			const retained = new Set<GenerationId>([
222				value.activeGenerationId,
223				rollbackGenerationIds[0],
224				rollbackGenerationIds[1],
225			]);
226			if (
227				retained.size !== 3 ||
228				value.lineageFloor.generationId !== rollbackGenerationIds[1] ||
229				deleteGenerationIds.some((generationId) => retained.has(generationId))
230			) {
231				invalid("reclamation input generations must be disjoint and floor-bound");
232			}
233			return Object.freeze({
234				activeGenerationId: value.activeGenerationId,
235				availabilityPolicyDigest: value.availabilityPolicyDigest,
236				closedEpoch: Number(value.closedEpoch),
237				expectedHead: cloneHead(expectedHead) as PresentHead,
238				lineageFloor: Object.freeze({
239					deleteGenerationIds,
240					expectedBaseExpectedHead: cloneHead(expectedBaseExpectedHead),
241					generationId: value.lineageFloor.generationId,
242					replacementBaseExpectedHead: cloneHead(replacementBaseExpectedHead) as Readonly<{
243						kind: "none";
244						objectId: StorageObjectId;
245					}>,
246				}),
247				objectId: value.objectId,
248				rollbackGenerationIds,
249			});
250		} catch (error) {
251			if (error instanceof AheReclamationError) throw error;
252			throw failure("AHE_RECLAMATION_INVALID_ARGUMENT", "reclamation input could not be inspected", error);
253		}
254	}
255	
256	function generationKey(objectId: StorageObjectId, generationId: GenerationId): string {
257		return `${objectId}\0${generationId}`;
258	}
259	
260	function promotionKey(promotion: AheReclamationPromotion): string {
261		return `${promotion.objectId}\0${promotion.generationId}\0${promotion.digest}`;
262	}
263	
264	function copyPromotions(value: unknown): readonly AheReclamationPromotion[] {
265		if (!isClosedArray(value)) corrupt("promotion scan was not a dense array");
266		const promotions: AheReclamationPromotion[] = [];
267		const keys = new Set<string>();
268		for (const candidate of value) {
269			if (
270				!isClosedRecord(candidate, ["digest", "generationId", "objectId"]) ||
271				!isStorageObjectId(candidate.objectId) ||
272				!isGenerationId(candidate.generationId) ||
273				!isBlobDigest(candidate.digest)
274			) {
275				corrupt("promotion scan contained a malformed row");
276			}
277			const promotion = Object.freeze({
278				digest: candidate.digest,
279				generationId: candidate.generationId,
280				objectId: candidate.objectId,
281			});
282			const key = promotionKey(promotion);
283			if (keys.has(key)) corrupt("promotion scan contained a duplicate row");
284			keys.add(key);
285			promotions.push(promotion);
286		}
287		return Object.freeze(promotions);
288	}
289	
290	function copyGenerations(value: unknown): readonly GenerationRecord[] {
291		if (!isClosedArray(value)) corrupt("generation scan was not a dense array");
292		const generations: GenerationRecord[] = [];
293		const keys = new Set<string>();
294		for (const candidate of value) {
295			const generation = copyGenerationRecord(candidate);
296			if (generation === undefined) corrupt("generation scan contained a malformed row");
297			const key = generationKey(generation.objectId, generation.generationId);
298			if (keys.has(key)) corrupt("generation scan contained a duplicate identity");
299			keys.add(key);
300			const recomputed = digestClosure(generation.closure);
301			if (!recomputed.ok || recomputed.value !== generation.closureDigest) {
302				corrupt("generation scan contained an invalid closure digest");
303			}
304			generations.push(cloneGeneration(generation));
305		}
306		return Object.freeze(generations);
307	}
308	
309	function copyBlobFacts(value: unknown): ReadonlyMap<BlobDigest, Readonly<{ byteLength: number; valid: boolean }>> {
310		if (!isClosedArray(value)) corrupt("blob observation scan was not a dense array");
311		const blobs = new Map<BlobDigest, Readonly<{ byteLength: number; valid: boolean }>>();
312		for (const candidate of value) {
313			if (
314				!isClosedRecord(candidate, ["bytes", "digest"]) ||
315				!isBlobDigest(candidate.digest) ||
316				!(candidate.bytes instanceof Uint8Array) ||
317				hasSharedBacking(candidate.bytes) ||
318				blobs.has(candidate.digest)
319			) {
320				corrupt("blob observation scan contained a malformed or duplicate row");
321			}
322			const recomputed = digestBlob(candidate.bytes);
323			blobs.set(
324				candidate.digest,
325				Object.freeze({
326					byteLength: candidate.bytes.byteLength,
327					valid: recomputed.ok && recomputed.value === candidate.digest,
328				})
329			);
330		}
331		return blobs;
332	}
333	
334	function verifyPromotionsAndBlobs(
335		generations: readonly GenerationRecord[],
336		promotions: readonly AheReclamationPromotion[],
337		blobs: ReadonlyMap<BlobDigest, Readonly<{ byteLength: number; valid: boolean }>>
338	): void {
339		const byGeneration = new Map<string, Set<BlobDigest>>();
340		const records = new Map(
341			generations.map((generation) => [generationKey(generation.objectId, generation.generationId), generation])
342		);
343		for (const promotion of promotions) {
344			const key = generationKey(promotion.objectId, promotion.generationId);
345			const generation = records.get(key);
346			const reference = generation?.closure.find(({ digest }) => digest === promotion.digest);
347			if (generation === undefined || reference === undefined)
348				corrupt("promotion did not belong to its generation closure");
349			const blob = blobs.get(promotion.digest);
350			if (blob === undefined || !blob.valid || blob.byteLength !== reference.byteLength) {
351				corrupt("promoted blob was missing, corrupt, or had the wrong length");
352			}
353			const observed = byGeneration.get(key) ?? new Set<BlobDigest>();
354			observed.add(promotion.digest);
355			byGeneration.set(key, observed);
356		}
357		for (const generation of generations) {
358			const observed = byGeneration.get(generationKey(generation.objectId, generation.generationId)) ?? new Set();
359			const required =
360				generation.state === "Complete" || generation.state === "Adopted" || generation.state === "Superseded";
361			if (
362				required &&
363				(observed.size !== generation.closure.length || generation.closure.some(({ digest }) => !observed.has(digest)))
364			) {
365				corrupt("complete generation did not have its exact promotion set");
366			}
367		}
368	}
369	
370	function parentMatches(child: GenerationRecord, parent: GenerationRecord, childRevision: number): boolean {
371		return (
372			child.baseExpectedHead.kind === "present" &&
373			child.baseExpectedHead.objectId === parent.objectId &&
374			child.baseExpectedHead.generationId === parent.generationId &&
375			child.baseExpectedHead.closureDigest === parent.closureDigest &&
376			child.baseExpectedHead.revision === childRevision - 1
377		);
378	}
379	
380	function sameIds(left: readonly GenerationId[], right: readonly GenerationId[]): boolean {
381		return left.length === right.length && left.every((value, index) => value === right[index]);
382	}
383	
384	/**
385	 * Produces the one pure deletion decision consumed inside native transactions.
386	 * @param request - Untrusted D.109a AHE subset.
387	 * @param snapshot - Complete decoded generation/promotion scan plus required blob observations.
388	 * @returns Frozen floor rewrite and exact physical deletion set.
389	 */
390	export function classifyAheReclamation(request: unknown, snapshot: AheReclamationSnapshot): AheReclamationDecision {
391		const input = captureAheReclamationInput(request);
392		try {
393			if (!isClosedRecord(snapshot, ["blobs", "generations", "head", "promotions"])) {
394				corrupt("native snapshot was not one exact record");
395			}
396			const head = copyExpectedHead(snapshot.head, input.objectId);
397			if (head === undefined) corrupt("native head was malformed or cross-object");
398			if (!headsEqual(head, input.expectedHead)) retry("head changed before reclamation");
399			const generations = copyGenerations(snapshot.generations);
400			const promotions = copyPromotions(snapshot.promotions);
401			const blobs = copyBlobFacts(snapshot.blobs);
402			verifyPromotionsAndBlobs(generations, promotions, blobs);
403	
404			const target = generations.filter(({ objectId }) => objectId === input.objectId);
405			const byId = new Map(target.map((generation) => [generation.generationId, generation]));
406			const active = byId.get(input.activeGenerationId);
407			if (
408				active === undefined ||
409				active.state !== "Adopted" ||
410				active.closureDigest !== input.expectedHead.closureDigest
411			) {
412				corrupt("active head did not bind one adopted generation");
413			}
414			const firstId = input.rollbackGenerationIds[0];
415			const floorId = input.rollbackGenerationIds[1];
416			if (active.baseExpectedHead.kind !== "present") corrupt("active generation did not retain a rollback parent");
417			const first = byId.get(active.baseExpectedHead.generationId);
418			if (first === undefined || first.baseExpectedHead.kind !== "present") {
419				corrupt("retained rollback lineage contained a gap");
420			}
421			const floor = byId.get(first.baseExpectedHead.generationId);
422			if (floor === undefined) corrupt("retained rollback lineage contained a gap");
423			if (first.generationId !== firstId || floor.generationId !== floorId) {
424				retry("planned rollback generations changed before reclamation");
425			}
426			if (
427				first.state !== "Superseded" ||
428				floor.state !== "Superseded" ||
429				!parentMatches(active, first, input.expectedHead.revision) ||
430				!parentMatches(first, floor, active.baseExpectedHead.revision)
431			) {
432				corrupt("retained rollback lineage was invalid");
433			}
434	
435			const retained = new Set([active.generationId, first.generationId, floor.generationId]);
436			const selected: GenerationRecord[] = [];
437			let replay = false;
438			let normalizedThisCall = false;
439			if (headsEqual(floor.baseExpectedHead, input.lineageFloor.expectedBaseExpectedHead)) {
440				normalizedThisCall = !headsEqual(
441					input.lineageFloor.expectedBaseExpectedHead,
442					input.lineageFloor.replacementBaseExpectedHead
443				);
444				let cursor = floor.baseExpectedHead;
445				let expectedRevision = first.baseExpectedHead.kind === "present" ? first.baseExpectedHead.revision : 0;
446				const visited = new Set<GenerationId>();
447				while (cursor.kind === "present") {
448					if (visited.has(cursor.generationId)) corrupt("reclamation prefix contained a cycle");
449					const generation = byId.get(cursor.generationId);
450					if (
451						generation === undefined ||
452						generation.state !== "Superseded" ||
453						cursor.objectId !== input.objectId ||
454						cursor.closureDigest !== generation.closureDigest ||
455						cursor.revision !== expectedRevision - 1
456					) {
457						corrupt("reclamation prefix contained a gap or invalid parent");
458					}
459					visited.add(generation.generationId);
460					selected.push(generation);
461					expectedRevision = cursor.revision;
462					cursor = generation.baseExpectedHead;
463				}
464				if (cursor.objectId !== input.objectId) corrupt("reclamation prefix terminated in another object");
465			} else if (headsEqual(floor.baseExpectedHead, input.lineageFloor.replacementBaseExpectedHead)) {
466				replay = true;
467				if (input.lineageFloor.deleteGenerationIds.some((generationId) => byId.has(generationId))) {
468					corrupt("normalized floor retained part of the requested prefix");
469				}
470			} else {
471				retry("lineage floor changed before reclamation");
472			}
473	
474			const selectedIds = selected.map(({ generationId }) => generationId).sort();
475			if (!replay && !sameIds(selectedIds, input.lineageFloor.deleteGenerationIds)) {
476				retry("requested generation prefix no longer matches the complete lineage");
477			}
478			const extras = target.filter(
479				({ generationId }) => !retained.has(generationId) && !selectedIds.includes(generationId)
480			);
481			if (extras.length !== 0) {
482				const requestedPrefix = new Set(input.lineageFloor.deleteGenerationIds);
483				if (
484					replay &&
485					extras.some(
486						({ baseExpectedHead }) =>
487							baseExpectedHead.kind === "present" && requestedPrefix.has(baseExpectedHead.generationId)
488					)
489				) {
490					corrupt("normalized replay retained a dangling parent into the reclaimed prefix");
491				}
492				retry("target generation set changed before reclamation");
493			}
494	
495			const selectedSet = new Set(selectedIds);
496			const deletePromotions = promotions.filter(
497				({ generationId, objectId }) => objectId === input.objectId && selectedSet.has(generationId)
498			);
499			const candidateDigests = new Set(deletePromotions.map(({ digest }) => digest));
500			const remainingGenerationReferences = new Set(
501				generations
502					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
503					.flatMap(({ closure }) => closure.map(({ digest }) => digest))
504			);
505			const remainingPromotionReferences = new Set(
506				promotions
507					.filter(({ generationId, objectId }) => objectId !== input.objectId || !selectedSet.has(generationId))
508					.map(({ digest }) => digest)
509			);
510			const deleteBlobDigests = [...candidateDigests]
511				.filter((digest) => !remainingGenerationReferences.has(digest) && !remainingPromotionReferences.has(digest))
512				.sort();
513			const rewrittenGeneration = cloneGeneration({
514				...floor,
515				baseExpectedHead: input.lineageFloor.replacementBaseExpectedHead,
516			});
517			return Object.freeze({
518				deleteBlobDigests: Object.freeze(deleteBlobDigests),
519				deleteGenerationIds: Object.freeze(normalizedThisCall ? selectedIds : []),
520				deletePromotions: Object.freeze(normalizedThisCall ? deletePromotions : []),
521				floor: Object.freeze({
522					generation: cloneGeneration(floor),
523					normalizedThisCall,
524					rewrittenGeneration,
525				}),
526				input,
527			});
528		} catch (error) {
529			if (error instanceof AheReclamationError) throw error;
530			throw failure("AHE_RECLAMATION_CORRUPT", "native snapshot could not be inspected", error);
531		}
532	}
533	
534	/**
535	 * Constructs the detached immutable receipt after exact native row counts pass.
536	 * @param decision - Shared classifier decision used by the transaction.
537	 * @returns Frozen receipt containing actual writes for this call.
538	 */
539	export function createAheReclamationReceipt(decision: AheReclamationDecision): AheReclamationReceipt {
540		const { input } = decision;
541		return Object.freeze({
542			activeGenerationId: input.activeGenerationId,
543			availabilityPolicyDigest: input.availabilityPolicyDigest,
544			closedEpoch: input.closedEpoch,
545			deletedBlobDigests: Object.freeze([...decision.deleteBlobDigests]),
546			deletedGenerationIds: Object.freeze([...decision.deleteGenerationIds]),
547			deletedPromotionCount: decision.deletePromotions.length,
548			expectedHead: cloneHead(input.expectedHead) as PresentHead,
549			floor: Object.freeze({
550				expectedFormerBaseExpectedHead: cloneHead(input.lineageFloor.expectedBaseExpectedHead),
551				generationId: input.lineageFloor.generationId,
552				normalizedThisCall: decision.floor.normalizedThisCall,
553				replacementBaseExpectedHead: cloneHead(input.lineageFloor.replacementBaseExpectedHead) as Readonly<{
554					kind: "none";
555					objectId: StorageObjectId;
556				}>,
557			}),
558			objectId: input.objectId,
559			reclaimedGenerationIds: Object.freeze([...input.lineageFloor.deleteGenerationIds]),
560			rollbackGenerationIds: Object.freeze([...input.rollbackGenerationIds]) as readonly [GenerationId, GenerationId],
561		});
562	}
563	
564	/**
565	 * Creates one frozen lifecycle or substrate error without widening the code set.
566	 * @param code - Closed error code.
567	 * @param message - Diagnostic summary.
568	 * @param cause - Optional substrate cause.
569	 * @returns Frozen classified error.
570	 */
571	export function createAheReclamationError(
572		code: AheReclamationErrorCode,
573		message: string,
574		cause?: unknown
575	): AheReclamationError {
576		return failure(code, message, cause);
577	}

  1	declare const storageObjectIdBrand: unique symbol;
  2	declare const generationIdBrand: unique symbol;
