 52	function loadSnapshot(connection: DatabaseSync, objectId: string): AheReclamationSnapshot {
 53		const parsedObjectId = parseStorageObjectId(objectId);
 54		if (!parsedObjectId.ok) throw createAheReclamationError("AHE_RECLAMATION_INVALID_ARGUMENT", "object ID invalid");
 55		const objectRow = connection.prepare("SELECT head_record FROM objects WHERE object_id = ?").get(objectId) as
 56			| Row
 57			| undefined;
 58		let head: ExpectedHead = { kind: "none", objectId: parsedObjectId.value };
 59		if (objectRow !== undefined && objectRow.head_record !== null) {
 60			const decoded = decodeHeadRecordV1(databaseBytes(objectRow.head_record));
 61			if (!decoded.ok || decoded.value.objectId !== objectId) {
 62				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "head row was malformed or misbound");
 63			}
 64			head = decoded.value;
 65		}
 66	
 67		const generations: GenerationRecord[] = [];
 68		for (const row of connection
 69			.prepare("SELECT object_id, generation_id, record FROM generations ORDER BY object_id, generation_id")
 70			.all() as Row[]) {
 71			const decoded = decodeGenerationRecordV1(databaseBytes(row.record));
 72			if (!decoded.ok || decoded.value.objectId !== row.object_id || decoded.value.generationId !== row.generation_id) {
 73				throw createAheReclamationError("AHE_RECLAMATION_CORRUPT", "generation row was malformed or misbound");
 74			}
 75			generations.push(decoded.value);
 76		}
 77	
 78		const promotions = (
 79			connection
 80				.prepare("SELECT object_id, generation_id, digest FROM promotions ORDER BY object_id, generation_id, digest")
 81				.all() as Row[]
 82		).map(
 83			(row) =>
 84				({ objectId: row.object_id, generationId: row.generation_id, digest: row.digest }) as AheReclamationPromotion
 85		);
 86		const blobs = [];
 87		for (const row of connection
 88			.prepare(
 89				"SELECT blobs.digest, blobs.bytes FROM blobs " +
 90					"INNER JOIN (SELECT DISTINCT digest FROM promotions) AS referenced ON referenced.digest = blobs.digest " +
 91					"ORDER BY blobs.digest"
 92			)
 93			.all() as Row[]) {
 94			blobs.push({ digest: row.digest, bytes: databaseBytes(row.bytes) });
 95		}
 96		return { blobs, generations, head, promotions } as AheReclamationSnapshot;
 97	}
