166				const deleteGeneration = this.connection.prepare(
167					"DELETE FROM generations WHERE object_id = ? AND generation_id = ?"
168				);
169				for (const generationId of decision.deleteGenerationIds) {
170					generationDeletes += changed(deleteGeneration.run(captured.objectId, generationId));
