 125	function installSchedulingLockMode(mode: SchedulingMode): InstalledLockMode {
 126		const ownDescriptor = Object.getOwnPropertyDescriptor(navigator, "locks");
 127		const nativeLocks = Reflect.get(navigator, "locks") as unknown;
 128		const nativeRequest =
 129			nativeLocks !== null && typeof nativeLocks === "object" ? Reflect.get(nativeLocks, "request") : undefined;
 130		const nativeAvailable = typeof nativeRequest === "function";
 131		const names: string[] = [];
 132		let delayedCallback: LockCallback | undefined;
 133		let requested = false;
 134		let resolveRequested!: () => void;
 135		const requestedPromise = new Promise<void>((resolvePromise) => {
 136			resolveRequested = resolvePromise;
 137		});
 138	
 139		const replaceLocks = (value: unknown): void => {
 140			Object.defineProperty(navigator, "locks", { configurable: true, value });
 141		};
 142		if (mode === "absent") {
 143			replaceLocks(undefined);
 144		} else if (mode === "off") {
 145			replaceLocks(Object.freeze({}));
 146		} else if (mode === "non-callable") {
 147			replaceLocks(Object.freeze({ request: 1 }));
 148		} else if (mode !== "native") {
 149			const locks = {
 150				request(this: unknown, name: string, _options: unknown, callback: LockCallback): Promise<unknown> {
 151					if (this !== locks) throw new TypeError("D109E_LOCK_RECEIVER_LOST");
 152					names.push(name);
 153					if (!requested) {
 154						requested = true;
 155						resolveRequested();
 156					}
 157					if (mode === "throw") throw new TypeError("D109E_INJECTED_LOCK_THROW");
 158					if (mode === "reject") return Promise.reject(new TypeError("D109E_INJECTED_LOCK_REJECTION"));
 159					if (mode === "abort") return Promise.reject(new DOMException("injected abort", "AbortError"));
 160					if (mode === "unavailable") return Promise.resolve(callback(null));
 161					if (mode === "granted") return Promise.resolve(callback(Object.freeze({ name })));
 162					if (mode === "timeout") return new Promise(() => undefined);
 163					delayedCallback = callback;
 164					return new Promise(() => undefined);
 165				},
 166			};
 167			replaceLocks(Object.freeze(locks));
 168		}
 169	
 170		return Object.freeze({
 171			invokeDelayed: async () => {
 172				if (delayedCallback === undefined) throw new TypeError(`D109E_DELAYED_CALLBACK_MISSING:${mode}`);
 173				await delayedCallback(Object.freeze({ name: names[0] }));
 174			},
 175			names,
 176			nativeAvailable,
 177			restore: () => {
 178				if (ownDescriptor === undefined) {
 179					Reflect.deleteProperty(navigator, "locks");
 180				} else {
 181					Object.defineProperty(navigator, "locks", ownDescriptor);
 182				}
 183			},
 184			waitUntilRequested: async () => {
 185				if (mode === "delayed" || mode === "stale-late") await requestedPromise;
 186			},
 187		});
 188	}
