 190	async function fiveGenerations(
 191		store: AheDurableStore,
 192		bytesForIndex: (index: number) => Uint8Array = (index) => Uint8Array.of(index, index + 1, index + 2),
 193		generationCount = 5
 194	): Promise<Readonly<{ input: Record<string, unknown>; records: readonly GenerationRecord[] }>> {
 195		let head: ExpectedHead = successful(await store.readHead(OBJECT_ID), "HEAD");
 196		const records = [];
 197		for (let index = 1; index <= generationCount; index += 1) {
 198			const generationId = index.toString(16).padStart(64, "0");
 199			const bytes = bytesForIndex(index);
 200			const digest = successful(digestBlob(bytes), "DIGEST");
 201			const closure = [{ byteLength: bytes.byteLength, digest }];
 202			successful(
 203				await store.beginGeneration({ baseExpectedHead: head, closure, generationId, objectId: OBJECT_ID }),
 204				"BEGIN"
 205			);
 206			successful(await store.putCachedBlob({ bytes, digest, generationId, objectId: OBJECT_ID }), "PUT");
 207			successful(await store.promoteReference({ digest, generationId, objectId: OBJECT_ID }), "PROMOTE");
 208			successful(await store.completeGeneration({ generationId, objectId: OBJECT_ID }), "COMPLETE");
 209			head = successful(await store.swapHead({ expectedHead: head, generationId, objectId: OBJECT_ID }), "SWAP").head;
 210		}
 211		records.push(...successful(await store.readGenerationPage({ limit: 16, objectId: OBJECT_ID }), "PAGE").generations);
 212		if (head.kind !== "present") throw new TypeError("D109C_BROWSER_HEAD_ABSENT");
 213		const byId = new Map(records.map((record) => [record.generationId, record]));
 214		const active = byId.get(head.generationId);
 215		const first =
 216			active?.baseExpectedHead.kind === "present" ? byId.get(active.baseExpectedHead.generationId) : undefined;
 217		const floor = first?.baseExpectedHead.kind === "present" ? byId.get(first.baseExpectedHead.generationId) : undefined;
 218		if (active === undefined || first === undefined || floor === undefined) throw new TypeError("D109C_BROWSER_LINEAGE");
 219		const retained = new Set([active.generationId, first.generationId, floor.generationId]);
 220		return {
 221			input: {
 222				activeGenerationId: active.generationId,
 223				availabilityPolicyDigest: POLICY_DIGEST,
 224				closedEpoch: 4,
 225				expectedHead: head,
 226				lineageFloor: {
 227					deleteGenerationIds: records
 228						.filter(({ generationId }) => !retained.has(generationId))
 229						.map(({ generationId }) => generationId)
 230						.sort(),
 231					expectedBaseExpectedHead: floor.baseExpectedHead,
 232					generationId: floor.generationId,
 233					replacementBaseExpectedHead: { kind: "none", objectId: OBJECT_ID },
 234				},
 235				objectId: OBJECT_ID,
 236				rollbackGenerationIds: [first.generationId, floor.generationId],
 237			},
 238			records,
 239		};
 240	}
