 242	async function run(databaseName: string): Promise<Record<string, unknown>> {
 243		const store = await createBrowserAheDurableStore({ databaseName });
 244		const maintenance = resolveBrowserAheReclamationMaintenance(store);
 245		if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 246		const memory = createMemoryAheDurableStore();
 247		const memoryDenied = resolveBrowserAheReclamationMaintenance(memory) === undefined;
 248		await memory.close();
 249		let liveStore: AheDurableStore | undefined = store;
 250		try {
 251			const { input } = await fiveGenerations(store);
 252			const receipt = await maintenance.reclaimClosedEpoch(input);
 253			await store.close();
 254			liveStore = undefined;
 255			const closedPromise = maintenance.reclaimClosedEpoch(input);
 256			const asynchronousClosed = closedPromise instanceof Promise;
 257			const closedCode = await failureCode(closedPromise);
 258			const invalidCode = await failureCode(maintenance.reclaimClosedEpoch({}));
 259			const reopened = await createBrowserAheDurableStore({ databaseName });
 260			liveStore = reopened;
 261			const reopenedMaintenance = resolveBrowserAheReclamationMaintenance(reopened);
 262			if (reopenedMaintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 263			const replay = await reopenedMaintenance.reclaimClosedEpoch(input);
 264			const head = successful(await reopened.readHead(OBJECT_ID), "REOPEN_HEAD");
 265			const bytes = Uint8Array.of(6, 7, 8);
 266			const digest = successful(digestBlob(bytes), "SUCCESSOR_DIGEST");
 267			const successorId = generationId(6);
 268			successful(
 269				await reopened.beginGeneration({
 270					baseExpectedHead: head,
 271					closure: [{ byteLength: bytes.byteLength, digest }],
 272					generationId: successorId,
 273					objectId: OBJECT_ID,
 274				}),
 275				"SUCCESSOR_BEGIN"
 276			);
 277			successful(
 278				await reopened.putCachedBlob({ bytes, digest, generationId: successorId, objectId: OBJECT_ID }),
 279				"SUCCESSOR_PUT"
 280			);
 281			successful(
 282				await reopened.promoteReference({ digest, generationId: successorId, objectId: OBJECT_ID }),
 283				"SUCCESSOR_PROMOTE"
 284			);
 285			successful(
 286				await reopened.completeGeneration({ generationId: successorId, objectId: OBJECT_ID }),
 287				"SUCCESSOR_COMPLETE"
 288			);
 289			const successor = successful(
 290				await reopened.swapHead({ expectedHead: head, generationId: successorId, objectId: OBJECT_ID }),
 291				"SUCCESSOR_SWAP"
 292			);
 293			return {
 294				asynchronousClosed,
 295				closedCode,
 296				copiedDenied: resolveBrowserAheReclamationMaintenance({ ...store }) === undefined,
 297				facadeKeys: [...Object.keys(store), ...Object.getOwnPropertyNames(Object.getPrototypeOf(store))]
 298					.filter((key) => key !== "constructor")
 299					.sort(),
 300				memoryDenied,
 301				invalidCode,
 302				proxyDenied: resolveBrowserAheReclamationMaintenance(new Proxy(store, {})) === undefined,
 303				receipt,
 304				replay,
 305				successor,
 306			};
 307		} finally {
 308			await liveStore?.close();
 309		}
 310	}
