 312	async function runPositiveControls(prefix: string): Promise<Record<string, unknown>> {
 313		const emptyStore = await createBrowserAheDurableStore({ databaseName: `${prefix}-empty` });
 314		try {
 315			const maintenance = resolveBrowserAheReclamationMaintenance(emptyStore);
 316			if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 317			const fixture = await fiveGenerations(emptyStore, undefined, 3);
 318			const receipt = await maintenance.reclaimClosedEpoch(fixture.input);
 319			if (receipt.deletedGenerationIds.length !== 0 || receipt.floor.normalizedThisCall) {
 320				throw new TypeError("D109C_BROWSER_EMPTY_PREFIX_INVALID");
 321			}
 322		} finally {
 323			await emptyStore.close();
 324		}
 325	
 326		const databaseName = `${prefix}-concurrent`;
 327		const firstStore = await createBrowserAheDurableStore({ databaseName });
 328		const secondStore = await createBrowserAheDurableStore({ databaseName });
 329		try {
 330			const fixture = await fiveGenerations(firstStore);
 331			const firstMaintenance = resolveBrowserAheReclamationMaintenance(firstStore);
 332			const secondMaintenance = resolveBrowserAheReclamationMaintenance(secondStore);
 333			if (firstMaintenance === undefined || secondMaintenance === undefined) {
 334				throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 335			}
 336			const receipts = await Promise.all([
 337				firstMaintenance.reclaimClosedEpoch(fixture.input),
 338				secondMaintenance.reclaimClosedEpoch(fixture.input),
 339			]);
 340			const deleted = receipts.map(({ deletedGenerationIds }) => deletedGenerationIds.length).sort();
 341			if (deleted.join(",") !== "0,2") throw new TypeError(`D109C_BROWSER_CONCURRENCY_INVALID:${deleted.join(",")}`);
 342			return Object.freeze({ concurrentDeletedCounts: Object.freeze(deleted), empty: true });
 343		} finally {
 344			await Promise.all([firstStore.close(), secondStore.close()]);
 345		}
 346	}
