 357	async function runPreparedCleanup(
 358		databaseName: string,
 359		input: Record<string, unknown>,
 360		mode: SchedulingMode
 361	): Promise<Record<string, unknown>> {
 362		const store = await createBrowserAheDurableStore({ databaseName });
 363		const maintenance = resolveBrowserAheReclamationMaintenance(store);
 364		if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 365		let transactionEntries = 0;
 366		installBrowserAheReclamationCrashObserver(store, (edge: BrowserAheReclamationCrashEdge) => {
 367			if (edge === "before-commit") transactionEntries += 1;
 368		});
 369		const locks = installSchedulingLockMode(mode);
 370		try {
 371			const receipt = await maintenance.reclaimClosedEpoch(input);
 372			if (mode === "stale-late") {
 373				await locks.invokeDelayed();
 374				await Promise.resolve();
 375			}
 376			return Object.freeze({
 377				names: Object.freeze([...locks.names]),
 378				nativeAvailable: locks.nativeAvailable,
 379				receipt,
 380				transactionEntries,
 381			});
 382		} finally {
 383			locks.restore();
 384			await store.close();
 385		}
 386	}
