 393	async function triggerVersionchange(databaseName: string): Promise<void> {
 394		await new Promise<void>((resolvePromise, reject) => {
 395			const request = indexedDB.open(databaseName, PHASE_5E_SCHEMA_VERSION + 1);
 396			request.addEventListener(
 397				"upgradeneeded",
 398				() => {
 399					request.transaction?.abort();
 400				},
 401				{ once: true }
 402			);
 403			request.addEventListener("error", () => resolvePromise(), { once: true });
 404			request.addEventListener("blocked", () => reject(new TypeError("D109E_VERSIONCHANGE_BLOCKED")), { once: true });
 405			request.addEventListener(
 406				"success",
 407				() => {
 408					request.result.close();
 409					reject(new TypeError("D109E_VERSIONCHANGE_UPGRADE_COMMITTED"));
 410				},
 411				{ once: true }
 412			);
 413		});
 414	}
