 416	async function runLifecycleScenario(
 417		databaseName: string,
 418		event: "close" | "versionchange"
 419	): Promise<Record<string, unknown>> {
 420		const input = await prepareSchedulingScenario(databaseName);
 421		const before = await databaseImage(databaseName);
 422		const store = await createBrowserAheDurableStore({ databaseName });
 423		const maintenance = resolveBrowserAheReclamationMaintenance(store);
 424		if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 425		let transactionEntries = 0;
 426		installBrowserAheReclamationCrashObserver(store, (edge: BrowserAheReclamationCrashEdge) => {
 427			if (edge === "before-commit") transactionEntries += 1;
 428		});
 429		const delayed = installSchedulingLockMode("delayed");
 430		let restored = false;
 431		try {
 432			const pending = maintenance.reclaimClosedEpoch(input);
 433			await delayed.waitUntilRequested();
 434			if (event === "close") await store.close();
 435			else await triggerVersionchange(databaseName);
 436			await delayed.invokeDelayed().catch(() => undefined);
 437			const code = await failureCode(pending);
 438			const unchangedBeforeTakeover = (await databaseImage(databaseName)) === before;
 439			delayed.restore();
 440			restored = true;
 441			const granted = installSchedulingLockMode("granted");
 442			try {
 443				const successor = await createBrowserAheDurableStore({ databaseName });
 444				try {
 445					const successorMaintenance = resolveBrowserAheReclamationMaintenance(successor);
 446					if (successorMaintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 447					const receipt = await successorMaintenance.reclaimClosedEpoch(input);
 448					return Object.freeze({ code, receipt, transactionEntries, unchangedBeforeTakeover });
 449				} finally {
 450					await successor.close();
 451				}
 452			} finally {
 453				granted.restore();
 454			}
 455		} finally {
 456			if (!restored) delayed.restore();
 457			await store.close();
 458		}
 459	}
