 461	async function advanceToGenerationSix(store: AheDurableStore): Promise<ExpectedHead> {
 462		const head = successful(await store.readHead(OBJECT_ID), "SCHEDULING_HEAD");
 463		const bytes = Uint8Array.of(6, 7, 8);
 464		const digest = successful(digestBlob(bytes), "SCHEDULING_DIGEST");
 465		const id = generationId(6);
 466		successful(
 467			await store.beginGeneration({
 468				baseExpectedHead: head,
 469				closure: [{ byteLength: bytes.byteLength, digest }],
 470				generationId: id,
 471				objectId: OBJECT_ID,
 472			}),
 473			"SCHEDULING_BEGIN"
 474		);
 475		successful(await store.putCachedBlob({ bytes, digest, generationId: id, objectId: OBJECT_ID }), "SCHEDULING_PUT");
 476		successful(await store.promoteReference({ digest, generationId: id, objectId: OBJECT_ID }), "SCHEDULING_PROMOTE");
 477		successful(await store.completeGeneration({ generationId: id, objectId: OBJECT_ID }), "SCHEDULING_COMPLETE");
 478		return successful(
 479			await store.swapHead({ expectedHead: head, generationId: id, objectId: OBJECT_ID }),
 480			"SCHEDULING_SWAP"
 481		).head;
 482	}
