 546	const AHE_STORES = [
 547		PHASE_2D_BLOBS_STORE,
 548		PHASE_2D_GENERATIONS_STORE,
 549		PHASE_2D_OBJECTS_STORE,
 550		PHASE_2D_PROMOTIONS_STORE,
 551	] as const;
