 553	async function withRawDatabase<T>(
 554		databaseName: string,
 555		mode: IDBTransactionMode,
 556		runTransaction: (transaction: IDBTransaction) => Promise<T>
 557	): Promise<T> {
 558		const database = await openDatabase(databaseName);
 559		try {
 560			const transaction = database.transaction(AHE_STORES, mode, { durability: "strict" });
 561			const completion = transactionDone(transaction);
 562			const value = await runTransaction(transaction);
 563			if (mode === "readwrite") transaction.commit();
 564			await completion;
 565			return value;
 566		} finally {
 567			database.close();
 568		}
 569	}
