 571	function normalized(value: unknown): unknown {
 572		if (value instanceof Uint8Array) return [...value];
 573		if (Array.isArray(value)) return value.map(normalized);
 574		if (typeof value === "object" && value !== null) {
 575			return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, normalized(item)]));
 576		}
 577		return value;
 578	}
