 585					generations: await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).getAll()),
 586					objects: await requestValue(transaction.objectStore(PHASE_2D_OBJECTS_STORE).getAll()),
 587					promotions: await requestValue(transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).getAll()),
 588				})
 589			)
