 593	async function generationRecord(transaction: IDBTransaction, id: string): Promise<GenerationRecord> {
 594		const row = (await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).get([OBJECT_ID, id]))) as
 595			| { readonly record?: unknown }
 596			| undefined;
 597		if (!(row?.record instanceof Uint8Array)) throw new TypeError("D109C_BROWSER_NATIVE_RECORD_MISSING");
 598		const decoded = decodeGenerationRecordV1(row.record);
 599		if (decoded.ok === false) throw new TypeError(`D109C_BROWSER_NATIVE_RECORD_INVALID:${decoded.reason}`);
 600		return decoded.value;
