 617	type MutableRequest = Record<string, unknown> & {
 618		expectedHead: Record<string, unknown>;
 619		lineageFloor: Record<string, unknown> & { deleteGenerationIds: string[] };
 620		rollbackGenerationIds: string[];
 621	};
 622	
 623	function mutableRequest(input: Record<string, unknown>): MutableRequest {
 624		return structuredClone(input) as MutableRequest;
 625	}
 626	
 627	async function applyMutant(
 628		databaseName: string,
 629		input: Record<string, unknown>,
 630		mutant: string
 631	): Promise<Readonly<{ code: string; request: MutableRequest }>> {
 632		const request = mutableRequest(input);
 633		const corrupt = "AHE_RECLAMATION_CORRUPT";
 634		const retry = "AHE_RECLAMATION_RETRY_REQUIRED";
 635		if (mutant === "head-different") {
 636			request.expectedHead.closureDigest = "f".repeat(64);
 637			return { code: retry, request };
 638		}
 639		if (mutant === "revision-stale") {
 640			request.expectedHead.revision = 4;
 641			return { code: retry, request };
 642		}
 643		if (mutant === "active-mismatch") {
 644			request.activeGenerationId = generationId(4);
 645			return { code: "AHE_RECLAMATION_INVALID_ARGUMENT", request };
 646		}
 647		if (mutant === "rollback-insufficient" || mutant === "rollback-wrong-countable-pair" || mutant === "floor-wrong") {
 648			const second = mutant === "rollback-insufficient" ? generationId(9) : generationId(2);
 649			request.rollbackGenerationIds = [
 650				mutant === "rollback-wrong-countable-pair" ? generationId(3) : generationId(4),
 651				second,
 652			];
 653			if (mutant === "rollback-wrong-countable-pair") {
 654				request.lineageFloor.deleteGenerationIds = [generationId(1), generationId(4)];
 655			} else if (mutant === "floor-wrong") {
 656				request.lineageFloor.deleteGenerationIds = [generationId(1), generationId(3)];
 657			}
 658			request.lineageFloor.generationId = second;
 659			request.lineageFloor.expectedBaseExpectedHead = noHead();
 660			return { code: retry, request };
 661		}
 662		if (mutant === "former-parent-wrong") {
 663			request.lineageFloor.expectedBaseExpectedHead = noHead();
 664			return { code: retry, request };
 665		}
 666		await withRawDatabase(databaseName, "readwrite", async (transaction) => {
 667			const first = await generationRecord(transaction, generationId(1));
 668			const second = await generationRecord(transaction, generationId(2));
 669			const active = await generationRecord(transaction, generationId(5));
 670			if (mutant === "identity-duplicate" || mutant === "generation-key-record-mismatch") {
 671				await replaceGeneration(transaction, first.generationId, second);
 672			} else if (mutant === "closure-changed") {
 673				await replaceGeneration(transaction, active.generationId, {
 674					...active,
 675					closure: second.closure,
 676					closureDigest: second.closureDigest,
 677				});
 678			} else if (mutant === "state-changed") {
 679				await replaceGeneration(transaction, active.generationId, { ...active, state: "Superseded" });
 680			} else if (mutant === "lineage-gap") {
 681				await requestValue(
 682					transaction
 683						.objectStore(PHASE_2D_PROMOTIONS_STORE)
 684						.delete([OBJECT_ID, first.generationId, first.closure[0]?.digest])
 685				);
 686				await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).delete([OBJECT_ID, first.generationId]));
 687			} else if (mutant === "lineage-cycle") {
 688				await replaceGeneration(transaction, first.generationId, {
 689					...first,
 690					baseExpectedHead: {
 691						closureDigest: second.closureDigest,
 692						generationId: second.generationId,
 693						kind: "present",
 694						objectId: OBJECT_ID,
 695						revision: 2,
 696					},
 697				});
 698			} else if (
 699				mutant === "surviving-branch" ||
 700				mutant === "extra-target-row" ||
 701				mutant === "post-state-dangling-parent"
 702			) {
 703				const id = generationId(mutant === "extra-target-row" ? 7 : mutant === "surviving-branch" ? 8 : 9);
 704				const extra: GenerationRecord = {
 705					...first,
 706					baseExpectedHead: mutant === "extra-target-row" ? noHead() : second.baseExpectedHead,
 707					generationId: id,
 708					state: "Staged",
 709				};
 710				await replaceGeneration(transaction, id, extra);
 711				if (mutant === "post-state-dangling-parent") {
 712					const floor = await generationRecord(transaction, generationId(3));
 713					await replaceGeneration(transaction, floor.generationId, { ...floor, baseExpectedHead: noHead() });
 714					for (const idToDelete of [generationId(1), generationId(2)]) {
 715						const record = await generationRecord(transaction, idToDelete);
 716						for (const reference of record.closure) {
 717							await requestValue(
 718								transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).delete([OBJECT_ID, idToDelete, reference.digest])
 719							);
 720						}
 721						await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).delete([OBJECT_ID, idToDelete]));
 722					}
 723				}
 724			} else if (mutant === "retained-blob-missing" || mutant === "retained-blob-corrupt") {
 725				const digest = active.closure[0]?.digest;
 726				if (digest === undefined) throw new TypeError("D109C_BROWSER_DIGEST_MISSING");
 727				if (mutant === "retained-blob-missing") {
 728					await requestValue(transaction.objectStore(PHASE_2D_BLOBS_STORE).delete(digest));
 729				} else {
 730					await requestValue(transaction.objectStore(PHASE_2D_BLOBS_STORE).put({ bytes: Uint8Array.of(0), digest }));
 731				}
 732			} else if (mutant === "promotion-missing") {
 733				await requestValue(
 734					transaction
 735						.objectStore(PHASE_2D_PROMOTIONS_STORE)
 736						.delete([OBJECT_ID, active.generationId, active.closure[0]?.digest])
 737				);
 738			} else if (mutant === "promotion-extra" || mutant === "promotion-wrong-digest") {
 739				const digest = second.closure[0]?.digest;
 740				if (digest === undefined) throw new TypeError("D109C_BROWSER_DIGEST_MISSING");
 741				await requestValue(
 742					transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).put({
 743						digest,
 744						generationId: active.generationId,
 745						objectId: OBJECT_ID,
 746					})
 747				);
 748			} else if (mutant === "target-generation-malformed") {
 749				await replaceGeneration(transaction, first.generationId, Uint8Array.of(0));
 750			} else if (mutant === "unrelated-generation-malformed") {
 751				await requestValue(
 752					transaction.objectStore(PHASE_2D_OBJECTS_STORE).put({ objectId: OTHER_OBJECT_ID, record: null })
 753				);
 754				await requestValue(
 755					transaction.objectStore(PHASE_2D_GENERATIONS_STORE).put({
 756						generationId: generationId(9),
 757						objectId: OTHER_OBJECT_ID,
 758						record: Uint8Array.of(0),
 759					})
 760				);
 761			} else if (mutant === "partial-replay") {
 762				const floor = await generationRecord(transaction, generationId(3));
 763				await replaceGeneration(transaction, floor.generationId, { ...floor, baseExpectedHead: noHead() });
 764				for (const reference of first.closure) {
 765					await requestValue(
 766						transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).delete([OBJECT_ID, first.generationId, reference.digest])
 767					);
 768				}
 769				await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).delete([OBJECT_ID, first.generationId]));
 770			}
 771		});
 772		return { code: mutant === "surviving-branch" || mutant === "extra-target-row" ? retry : corrupt, request };
 773	}
 774	
 775	function countFault(mutant: string): "blob delete" | "floor rewrite" | "generation delete" | "promotion delete" {
 776		switch (mutant) {
 777			case "floor-update-count":
 778				return "floor rewrite";
 779			case "promotion-delete-count":
 780				return "promotion delete";
 781			case "generation-delete-count":
