 790	async function runMutantMatrix(prefix: string): Promise<Record<string, unknown>> {
 791		const cases = [...LINEAGE_MUTANTS, ...CORRUPTION_MUTANTS, ...COUNT_MUTANTS];
 792		const results: Array<Readonly<{ code: string; mutant: string; poisoned: boolean }>> = [];
 793		for (const mutant of cases) {
 794			const databaseName = `${prefix}-${mutant}`;
 795			const store = await createBrowserAheDurableStore({ databaseName });
 796			const maintenance = resolveBrowserAheReclamationMaintenance(store);
 797			if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 798			try {
 799				const { input } = await fiveGenerations(store);
 800				let request = mutableRequest(input);
 801				let expectedCode = "AHE_RECLAMATION_CORRUPT";
 802				if ((COUNT_MUTANTS as readonly string[]).includes(mutant)) {
 803					installBrowserAheReclamationCountFault(store, countFault(mutant));
 804				} else {
 805					({ code: expectedCode, request } = await applyMutant(databaseName, input, mutant));
 806				}
 807				const before = await databaseImage(databaseName);
 808				let error: unknown;
 809				try {
 810					await maintenance.reclaimClosedEpoch(request);
 811				} catch (candidate) {
 812					error = candidate;
 813				}
 814				const code =
 815					typeof error === "object" && error !== null && typeof Reflect.get(error, "code") === "string"
 816						? String(Reflect.get(error, "code"))
 817						: undefined;
 818				if (code !== expectedCode || !Object.isFrozen(error)) {
 819					throw new TypeError(`D109C_BROWSER_MUTANT_CODE:${mutant}:${String(code)}:${expectedCode}`);
 820				}
 821				if ((await databaseImage(databaseName)) !== before) {
 822					throw new TypeError(`D109C_BROWSER_MUTANT_COMMITTED:${mutant}`);
 823				}
 824				const ordinary = await store.readHead(OBJECT_ID);
 825				const poisoned = ordinary.ok === false && ordinary.reason === "STORE_POISONED";
 826				if (expectedCode === "AHE_RECLAMATION_CORRUPT" ? !poisoned : ordinary.ok === false) {
 827					throw new TypeError(`D109C_BROWSER_MUTANT_LIFECYCLE:${mutant}`);
 828				}
 829				results.push(Object.freeze({ code: expectedCode, mutant, poisoned }));
 830			} finally {
 831				await store.close();
 832			}
 833		}
 834		return Object.freeze({ cases: Object.freeze(results), total: results.length });
 835	}
