 872	async function runReferenceMatrix(prefix: string): Promise<Record<string, unknown>> {
 873		const passed: string[] = [];
 874		for (const caseId of REFERENCE_CASES) {
 875			const databaseName = `${prefix}-${caseId}`;
 876			const store = await createBrowserAheDurableStore({ databaseName });
 877			const maintenance = resolveBrowserAheReclamationMaintenance(store);
 878			if (maintenance === undefined) throw new TypeError("D109C_BROWSER_MAINTENANCE_MISSING");
 879			try {
 880				const fixture = await fiveGenerations(store, (index) =>
 881					caseId === "retained-shared-blob" && index === 3
 882						? Uint8Array.of(1, 2, 3)
 883						: Uint8Array.of(index, index + 1, index + 2)
 884				);
 885				const firstDigest = fixture.records.find(({ generationId: id }) => id === generationId(1))?.closure[0]?.digest;
 886				const secondDigest = fixture.records.find(({ generationId: id }) => id === generationId(2))?.closure[0]?.digest;
 887				if (firstDigest === undefined || secondDigest === undefined) {
 888					throw new TypeError("D109C_BROWSER_REFERENCE_DIGEST_MISSING");
 889				}
 890				if (caseId === "cross-object-shared-blob") {
 891					await addOtherGeneration(store, {
 892						closure: [{ byteLength: 3, digest: firstDigest }],
 893						complete: true,
 894						promote: [firstDigest],
 895					});
 896				} else if (caseId === "unrelated-orphan-retained") {
 897					const bytes = Uint8Array.of(240, 241, 242);
 898					const digest = successful(digestBlob(bytes), "ORPHAN_DIGEST");
 899					await withRawDatabase(databaseName, "readwrite", async (transaction) => {
 900						await requestValue(transaction.objectStore(PHASE_2D_BLOBS_STORE).put({ bytes, digest }));
 901					});
 902				} else if (caseId === "staged-partial-promotions" || caseId === "discarded-partial-promotions") {
 903					await addOtherGeneration(store, {
 904						closure: [
 905							{ byteLength: 3, digest: firstDigest },
 906							{ byteLength: 3, digest: secondDigest },
 907						].sort((left, right) => left.digest.localeCompare(right.digest)),
 908						discard: caseId === "discarded-partial-promotions",
 909						promote: [firstDigest],
 910					});
 911				}
 912				const before = await blobCount(databaseName);
 913				const receipt = await maintenance.reclaimClosedEpoch(fixture.input);
 914				if (receipt.deletedGenerationIds.join(",") !== [generationId(1), generationId(2)].join(",")) {
 915					throw new TypeError(`D109C_BROWSER_REFERENCE_GENERATIONS:${caseId}`);
 916				}
 917				const first = successful(await store.getBlob(firstDigest), "REFERENCE_FIRST_BLOB");
 918				if (
 919					caseId === "retained-shared-blob" ||
 920					caseId === "cross-object-shared-blob" ||
 921					caseId === "staged-partial-promotions" ||
 922					caseId === "discarded-partial-promotions"
 923				) {
 924					if (first === null) throw new TypeError(`D109C_BROWSER_REFERENCE_LOST:${caseId}`);
 925				} else if (caseId === "candidate-only-blob") {
 926					if (first !== null || successful(await store.getBlob(secondDigest), "REFERENCE_SECOND_BLOB") !== null) {
 927						throw new TypeError("D109C_BROWSER_CANDIDATE_BLOB_RETAINED");
 928					}
 929				} else if ((await blobCount(databaseName)) !== before - 2) {
 930					throw new TypeError("D109C_BROWSER_ORPHAN_REMOVED");
 931				}
 932				passed.push(caseId);
 933			} finally {
 934				await store.close();
 935			}
 936		}
 937		return Object.freeze({ cases: Object.freeze(passed), total: passed.length });
 938	}
