 948	async function reopenedShape(databaseName: string): Promise<ReopenShape> {
 949		return withRawDatabase(databaseName, "readonly", async (transaction) => {
 950			const generations = (await requestValue(transaction.objectStore(PHASE_2D_GENERATIONS_STORE).getAll())) as Array<{
 951				readonly generationId: string;
 952				readonly objectId: string;
 953				readonly record: Uint8Array;
 954			}>;
 955			const target = generations
 956				.filter(({ objectId }) => objectId === OBJECT_ID)
 957				.sort((left, right) => left.generationId.localeCompare(right.generationId));
 958			const floor = target.find(({ generationId: id }) => id === generationId(3));
 959			if (floor === undefined) throw new TypeError("D109C_BROWSER_REOPEN_FLOOR_MISSING");
 960			const decodedFloor = decodeGenerationRecordV1(floor.record);
 961			if (decodedFloor.ok === false) throw new TypeError("D109C_BROWSER_REOPEN_FLOOR_INVALID");
 962			const object = (await requestValue(transaction.objectStore(PHASE_2D_OBJECTS_STORE).get(OBJECT_ID))) as
 963				| { readonly record?: unknown }
 964				| undefined;
 965			if (!(object?.record instanceof Uint8Array)) throw new TypeError("D109C_BROWSER_REOPEN_HEAD_MISSING");
 966			const head = decodeHeadRecordV1(object.record);
 967			if (head.ok === false || head.value.kind !== "present") throw new TypeError("D109C_BROWSER_REOPEN_HEAD_INVALID");
 968			return Object.freeze({
 969				blobs: await requestValue(transaction.objectStore(PHASE_2D_BLOBS_STORE).count()),
 970				floorNormalized: decodedFloor.value.baseExpectedHead.kind === "none",
 971				generationIds: Object.freeze(target.map(({ generationId: id }) => id)),
 972				headGenerationId: head.value.generationId,
 973				promotions: await requestValue(transaction.objectStore(PHASE_2D_PROMOTIONS_STORE).count()),
 974			});
 975		});
 976	}
