 978	async function terminateWorkerAt(databaseName: string, edge: string): Promise<void> {
 979		await new Promise<void>((resolvePromise, reject) => {
 980			const worker = new Worker(workerUrl(), { type: "module" });
 981			const timer = setTimeout(() => {
 982				worker.terminate();
 983				reject(new TypeError(`D109C_BROWSER_WORKER_TIMEOUT:${edge}`));
 984			}, 15_000);
 985			worker.addEventListener("error", (event) => {
 986				clearTimeout(timer);
 987				worker.terminate();
 988				reject(new TypeError(`D109C_BROWSER_WORKER_ERROR:${edge}:${event.message}`));
 989			});
 990			worker.addEventListener("message", (event: MessageEvent<Record<string, unknown>>) => {
 991				if (event.data.kind === "ready") {
 992					worker.postMessage({ databaseName, edge });
 993				} else if (event.data.kind === "checkpoint" && event.data.edge === edge) {
 994					clearTimeout(timer);
 995					worker.terminate();
 996					resolvePromise();
 997				} else if (event.data.kind === "worker-error") {
 998					clearTimeout(timer);
 999					worker.terminate();
1000					reject(new TypeError(`D109C_BROWSER_WORKER_FAILURE:${edge}:${String(event.data.message)}`));
1001				}
1002			});
1003		});
1004	}
