1006	async function runCrashMatrix(prefix: string): Promise<Record<string, unknown>> {
1007		const edges = [
1008			"after-floor-rewrite",
1009			"after-promotion-delete",
1010			"after-generation-delete",
1011			"after-blob-delete",
1012			"before-commit",
1013			"after-commit",
1014		] as const;
1015		const results: Array<Readonly<{ edge: string; state: "complete-new" | "old" }>> = [];
1016		for (const edge of edges) {
1017			const databaseName = `${prefix}-${edge}`;
1018			await terminateWorkerAt(databaseName, edge);
1019			const shape = await reopenedShape(databaseName);
1020			const old =
1021				shape.generationIds.length === 5 && !shape.floorNormalized && shape.promotions === 5 && shape.blobs === 5;
1022			const completeNew =
1023				shape.generationIds.join(",") === generationId(3) + "," + generationId(4) + "," + generationId(5) &&
1024				shape.floorNormalized &&
1025				shape.promotions === 3 &&
1026				shape.blobs === 3;
1027			if (Number(old) + Number(completeNew) !== 1 || completeNew !== (edge === "after-commit")) {
1028				throw new TypeError(`D109C_BROWSER_CRASH_STATE:${edge}:${JSON.stringify(shape)}`);
1029			}
1030			if (shape.headGenerationId !== generationId(5)) throw new TypeError(`D109C_BROWSER_CRASH_HEAD:${edge}`);
1031			results.push(Object.freeze({ edge, state: completeNew ? "complete-new" : "old" }));
1032		}
1033		return Object.freeze({ cases: Object.freeze(results), total: results.length });
1034	}
