394	async function addOtherGeneration(
395		store: AheDurableStore,
396		input: Readonly<{
397			closure: readonly GenerationRecord["closure"][number][];
398			complete?: boolean;
399			discard?: boolean;
400			promote: readonly GenerationRecord["closure"][number]["digest"][];
401		}>
402	): Promise<void> {
403		const generationId = d109cGenerationId(9);
404		const head = successful(await store.readHead(D109C_OTHER_OBJECT), "OTHER_HEAD");
405		successful(
406			await store.beginGeneration({
407				baseExpectedHead: head,
408				closure: input.closure,
409				generationId,
410				objectId: D109C_OTHER_OBJECT,
411			}),
412			"OTHER_BEGIN"
413		);
414		for (const digest of input.promote) {
415			successful(await store.promoteReference({ digest, generationId, objectId: D109C_OTHER_OBJECT }), "OTHER_PROMOTE");
416		}
417		if (input.complete) {
418			successful(await store.completeGeneration({ generationId, objectId: D109C_OTHER_OBJECT }), "OTHER_COMPLETE");
419		}
420		if (input.discard) {
421			successful(await store.discardGeneration({ generationId, objectId: D109C_OTHER_OBJECT }), "OTHER_DISCARD");
422		}
423	}
