 61	async function eventually(check: () => Promise<boolean>, attempts = 100): Promise<void> {
 62		for (let attempt = 0; attempt < attempts; attempt += 1) {
 63			if (await check()) return;
 64			await new Promise<void>((resolvePromise) => setTimeout(resolvePromise, 10));
 65		}
 66		throw new TypeError("D109D_EVENTUALLY_TIMED_OUT");
 67	}
