 87	function receiptMutant(
 88		name: (typeof D109D_RECEIPT_MUTANTS)[number],
 89		fixture: Awaited<ReturnType<typeof openD109dHotFixture>>,
 90		receipts: Awaited<ReturnType<typeof createD109dReceipts>>
 91	): unknown {
 92		const ahe = structuredClone(receipts.aheReceipt) as Record<string, unknown>;
 93		const issuance = structuredClone(receipts.issuanceReceipt) as Record<string, unknown>;
 94		const input: Record<string, unknown> = { aheReceipt: ahe, issuanceReceipt: issuance, successor: fixture.successor };
 95		switch (name) {
 96			case "missing-ahe-receipt":
 97				delete input.aheReceipt;
 98				return input;
 99			case "missing-issuance-receipt":
100				delete input.issuanceReceipt;
101				return input;
102			case "extra-input-key":
103				input.extra = true;
104				return input;
105			case "accessor-input": {
106				const accessor = { issuanceReceipt: issuance, successor: fixture.successor };
107				Object.defineProperty(accessor, "aheReceipt", { enumerable: true, get: () => ahe });
108				return accessor;
109			}
110			case "proxy-input":
111				return new Proxy(input, {
112					ownKeys: (): never => {
113						throw new TypeError("D109D_HOSTILE_PROXY");
114					},
115				});
116			case "issuance-extra-key":
117				issuance.extra = true;
118				return input;
119			case "ahe-extra-key":
120				ahe.extra = true;
121				return input;
122			case "shared-object":
123				record(issuance.scope).objectId = `creator:${"b".repeat(32)}`;
124				return input;
125			case "shared-closed-epoch":
126				issuance.closedEpoch = Number(issuance.closedEpoch) + 1;
127				return input;
128			case "issuance-scope-author":
129				record(issuance.scope).author = "b".repeat(64);
130				return input;
131			case "issuance-scope-object":
132				record(issuance.scope).objectId = `creator:${"c".repeat(32)}`;
133				return input;
134			case "snapshot-manifest-digest":
135				issuance.snapshotManifestDigest = changedDigest(issuance.snapshotManifestDigest);
136				return input;
137			case "commit-qc-digest":
138				record(issuance.commitQcRef).digest = changedDigest(record(issuance.commitQcRef).digest);
139				return input;
140			case "commit-qc-byte-length":
141				record(issuance.commitQcRef).byteLength = Number(record(issuance.commitQcRef).byteLength) + 1;
142				return input;
143			case "commit-qc-duplicate":
144				record(issuance.commitQcRef).digest = "d".repeat(64);
145				return input;
146			case "ahe-head-object": {
147				const objectId = `creator:${"d".repeat(32)}`;
148				ahe.objectId = objectId;
149				record(issuance.scope).objectId = objectId;
150				record(ahe.expectedHead).objectId = objectId;
151				record(record(ahe.floor).expectedFormerBaseExpectedHead).objectId = objectId;
152				record(record(ahe.floor).replacementBaseExpectedHead).objectId = objectId;
153				return input;
154			}
155			case "ahe-head-revision":
156				record(ahe.expectedHead).revision = Number(record(ahe.expectedHead).revision) + 1;
157				return input;
158			case "ahe-head-generation": {
159				const generationId = changedDigest(record(ahe.expectedHead).generationId);
160				record(ahe.expectedHead).generationId = generationId;
161				ahe.activeGenerationId = generationId;
162				return input;
163			}
164			case "ahe-active-generation":
165				ahe.activeGenerationId = changedDigest(ahe.activeGenerationId);
166				return input;
167			case "ahe-availability-policy":
168				ahe.availabilityPolicyDigest = changedDigest(ahe.availabilityPolicyDigest);
169				return input;
170			case "ahe-rollback-first":
171				values(ahe.rollbackGenerationIds)[0] = values(ahe.rollbackGenerationIds)[1];
172				return input;
173			case "ahe-rollback-floor":
174				values(ahe.rollbackGenerationIds)[1] = values(ahe.rollbackGenerationIds)[0];
175				return input;
176			case "ahe-floor-generation":
177				record(ahe.floor).generationId = changedDigest(record(ahe.floor).generationId);
178				return input;
179			case "ahe-floor-former-head":
180				record(record(ahe.floor).expectedFormerBaseExpectedHead).objectId = `creator:${"e".repeat(32)}`;
181				return input;
182			case "ahe-floor-replacement-head":
183				record(ahe.floor).replacementBaseExpectedHead = structuredClone(ahe.expectedHead);
184				return input;
185			case "issuance-partial-prefix":
186				input.issuanceReceipt = receipts.issuancePartialReceipt;
187				return input;
188			case "issuance-boundary-above":
189				issuance.prunedThroughAuthorSequence = Number(issuance.prunedThroughAuthorSequence) + 1;
190				record(issuance.observedLineage).next = Number(record(issuance.observedLineage).next) + 1;
191				return input;
192		}
